export const modelAnswers: Record<number, {text:string;compare:string;source:string}> = {
  "1": {
    "text": "Das lyrische Ich begegnet im Erinnern den Gestalten seiner früheren Dichtung und dem eigenen vergangenen Leben. Verlorene Freunde, frühe Liebe und die ersten dichterischen Versuche werden wieder gegenwärtig. Der Stoff entsteht aus Erinnerung und Verlust; das Vergangene erhält im Schreiben eine neue, zugleich schmerzlich gebrochene Nähe.",
    "compare": "Belege den Übergang von den wiederkehrenden Gestalten zu den Erinnerungen an frühere Menschen. Eine rein biografische Nacherzählung ersetzt die Deutung des lyrischen Ichs nicht.",
    "source": "https://projekt-gutenberg.org/authors/johann-wolfgang-von-goethe/books/faust-eine-tragoedie/chapter/2/"
  },
  "2": {
    "text": "Der Direktor braucht ein erfolgreiches, gut besuchtes Theater. Der Dichter verteidigt künstlerischen Anspruch und die innere Einheit des Werks. Die lustige Person betont gegenwärtiges Vergnügen, Spiel und die Wirkung auf lebendige Menschen. Der Konflikt betrifft damit nicht einfach gute und schlechte Kunst, sondern verschiedene Aufgaben des Theaters.",
    "compare": "Vergleiche eine Forderung jeder Figur. Auch die lustige Person hat eine eigene Kunstauffassung und ist nicht bloss Sprachrohr des Direktors.",
    "source": "https://projekt-gutenberg.org/authors/johann-wolfgang-von-goethe/books/faust-eine-tragoedie/chapter/3/"
  },
  "3": {
    "text": "Der Direktor sieht eine heterogene, nach Unterhaltung und Abwechslung verlangende Menge. Der Dichter fürchtet die Zerstreuung und das rasche Urteil dieses Publikums; er denkt an dauerhafte künstlerische Wirkung. Die lustige Person nimmt die Zuschauer als gegenwärtige Menschen ernst und will sie unmittelbar erreichen.",
    "compare": "Zeige Unterschiede zwischen der ökonomischen, der ästhetischen und der spielerischen Perspektive. Ein abschliessendes eigenes Urteil muss diese Unterschiede berücksichtigen.",
    "source": "https://projekt-gutenberg.org/authors/johann-wolfgang-von-goethe/books/faust-eine-tragoedie/chapter/3/"
  },
  "4": {
    "text": "Der Direktor beendet den Streit mit einem Produktionsauftrag: Das Theater soll seine verfügbaren Mittel ausschöpfen, Vielfalt, Handlung und Wirkung bieten und die ganze Welt auf die Bühne bringen. Er löst den theoretischen Gegensatz nicht argumentativ auf, sondern setzt seine praktische Entscheidungsmacht durch.",
    "compare": "Belege die Arbeitsanweisungen am Ende des Vorspiels. Unterscheide ein Ende der Diskussion von einer Einigung über Kunst.",
    "source": "https://projekt-gutenberg.org/authors/johann-wolfgang-von-goethe/books/faust-eine-tragoedie/chapter/3/"
  },
  "5": {
    "text": "Raphael besingt den kosmischen Gang der Sonne, Gabriel die rasche Bewegung der Erde und den Wechsel ihrer Erscheinungen, Michael die gewaltigen Stürme. Gemeinsam loben sie die unbegreifliche Grösse und Ordnung der Schöpfung. Auch zerstörerische Naturkräfte erscheinen in dieses Ganze eingebunden. Ihr Daseinsgefühl lässt sich als Ehrfurcht und Sicherheit in einer göttlichen Ordnung beschreiben.",
    "compare": "Ordne jedem Erzengel ein eigenes Bild zu und vergleiche das gemeinsame Lob. Eine Beschreibung der Filmstimmen ist ein zusätzlicher Inszenierungsbeleg, kein Ersatz für die Bilder des Textes.",
    "source": "https://projekt-gutenberg.org/authors/johann-wolfgang-von-goethe/books/faust-eine-tragoedie/chapter/4/"
  },
  "6": {
    "text": "Mephisto kontert den feierlichen Lobgesang mit Spott und lenkt den Blick auf das Elend des Menschen. Dessen Vernunft mache ihn aus seiner Sicht nicht besser, sondern auf besondere Weise töricht und grausam. Seine Bemerkung über Gottes verlerntes Lachen gehört zum ironischen, vertraulich-provokanten Gesprächston; sie ist kein neutraler Bericht. Aufklärerische Vernunftzuversicht wird angegriffen, doch Mephistos Spott ist nicht ohne Weiteres Goethes Urteil über die gesamte Aufklärung.",
    "compare": "Vergleiche den Tonwechsel und Mephistos Tiervergleich. Eine differenzierte Antwort kann zwischen Kritik am Vernunftmissbrauch und pauschaler Vernunftverachtung unterscheiden.",
    "source": "https://projekt-gutenberg.org/authors/johann-wolfgang-von-goethe/books/faust-eine-tragoedie/chapter/4/"
  },
  "7": {
    "text": "Mephisto sieht in Faust einen unzufriedenen Menschen, dessen Ansprüche ihn zwischen irdischen und höheren Wünschen zerreissen. Gott versteht dieselbe Unruhe als noch verworrenes, aber entwicklungsfähiges Streben. Mephisto möchte Faust vom rechten Weg abbringen; Gott erlaubt die Versuchung während Fausts Leben. Die Wette entsteht aus zwei gegensätzlichen Deutungen desselben Strebens.",
    "compare": "Vergleiche Gottes Vertrauen auf Entwicklung mit Mephistos Erwartung der Ablenkbarkeit. Gott und Mephisto beschreiben nicht zwei verschiedene Personen.",
    "source": "https://projekt-gutenberg.org/authors/johann-wolfgang-von-goethe/books/faust-eine-tragoedie/chapter/4/"
  },
  "8": {
    "text": "Mephisto darf Faust zu Lebzeiten versuchen und will ihn auf seinen eigenen Weg führen. Er rechnet damit, Fausts Unzufriedenheit in niedrigere Befriedigungen umzulenken. Gott erwartet, dass der strebende Mensch zwar irrt, aber seine grundlegende Orientierung nicht endgültig verliert. Mephisto versteht die Aufgabe als Gewinn einer Seele; im göttlichen Zusammenhang kann sein Widerspruch menschliche Tätigkeit gerade anregen.",
    "compare": "Belege Erlaubnis, zeitliche Grenze und unterschiedliche Erwartungen getrennt. Die Vereinbarung ist nicht identisch mit dem späteren Vertrag zwischen Faust und Mephisto.",
    "source": "https://projekt-gutenberg.org/authors/johann-wolfgang-von-goethe/books/faust-eine-tragoedie/chapter/4/"
  },
  "9": {
    "text": "Faust hat Philosophie, Juristerei, Medizin und Theologie studiert und ist ein erfahrener akademischer Lehrer. Trotzdem meint er, den entscheidenden Fragen nicht nähergekommen zu sein. Titel und Überlegenheit gegenüber anderen Gelehrten ersetzen für ihn weder Gewissheit noch ein erfülltes Leben. Seine Krise betrifft den Anspruch, das Ganze zu erkennen, nicht bloss mangelnden beruflichen Erfolg.",
    "compare": "Nenne die vier Studienbereiche und verbinde sie mit seiner Bilanz. Dass Faust sein Wissen entwertet, beweist nicht, dass er tatsächlich nichts gelernt hat.",
    "source": "https://projekt-gutenberg.org/authors/johann-wolfgang-von-goethe/books/faust-eine-tragoedie/chapter/5/"
  },
  "10": {
    "text": "Faust will die inneren Zusammenhänge der Welt unmittelbar erkennen und erfahren. Das angehäufte Wissen bleibt hinter diesem umfassenden Anspruch zurück. Er versucht die Überschreitung durch Magie, Naturzeichen und Geisterbeschwörung; später erscheint selbst der Tod als Ausweg. Das Dilemma liegt zwischen einem grenzenlosen Erkenntniswunsch und endlichen menschlichen Möglichkeiten.",
    "compare": "Unterscheide Ziel, Hindernis und einzelne Auswege. Eine Kritik an Fausts überhöhtem Anspruch ist möglich, wenn sie am Text begründet wird.",
    "source": "https://projekt-gutenberg.org/authors/johann-wolfgang-von-goethe/books/faust-eine-tragoedie/chapter/5/"
  },
  "11": {
    "text": "Das Zeichen des Makrokosmos im Buch des Nostradamus lässt Faust vorübergehend eine lebendige Einheit des Weltganzen schauen. Er erlebt Begeisterung, erkennt aber, dass das Bild ihm die erhoffte unmittelbare Teilnahme nicht verschafft. Er bleibt Betrachter und wendet sich dem Erdgeist zu.",
    "compare": "Belege zuerst die Erhebung und anschliessend den enttäuschten Wechsel. Das Zeichen ist für Faust bedeutsam, aber keine dauerhaft gelungene Erkenntnis.",
    "source": "https://projekt-gutenberg.org/authors/johann-wolfgang-von-goethe/books/faust-eine-tragoedie/chapter/5/"
  },
  "12": {
    "text": "Faust beschwört den Erdgeist, weil er an der lebendigen Tätigkeit der Welt teilhaben will. Die Erscheinung überfordert ihn; sein Anspruch auf Ebenbürtigkeit wird zurückgewiesen. Der Geist macht deutlich, dass Faust nicht mit jeder von ihm angerufenen Macht identisch ist. Nach dem Verschwinden bleiben Erschütterung und eine erneut erfahrene Grenze.",
    "compare": "Ordne die Zurückweisung dem Erdgeist zu. Fausts momentanes Selbstgefühl und die Antwort des Geistes dürfen nicht miteinander verwechselt werden.",
    "source": "https://projekt-gutenberg.org/authors/johann-wolfgang-von-goethe/books/faust-eine-tragoedie/chapter/5/"
  },
  "13": {
    "text": "Wagner setzt auf gelehrte Arbeit, Bücher, Überlieferung und die Kunst des Vortrags. Faust verlangt ein Wissen, das aus innerer Erfahrung kommt und wirklich ergreift. Wagner wirkt aus Fausts Sicht eng und selbstzufrieden; zugleich verkörpert er geduldige, methodische Arbeit, die Faust abwertet. Man kann Fausts Überheblichkeit kritisieren, ohne seinen Erkenntniswunsch geringzuschätzen.",
    "compare": "Vergleiche die Ansprüche beider an Erkenntnis und Vermittlung. Eine eigene Wagnerbewertung sollte seine Stärken und Begrenzungen nennen.",
    "source": "https://projekt-gutenberg.org/authors/johann-wolfgang-von-goethe/books/faust-eine-tragoedie/chapter/5/"
  },
  "14": {
    "text": "Ein faustischer Unterrichtszugang fragt nach einem Problem, experimentiert und will einen Zusammenhang selbst begreifen. Ein wagnerscher Zugang sammelt gesichertes Wissen und übt dessen geordnete Vermittlung. Für eine Projektarbeit könnte ich den faustischen Antrieb wählen, würde ihn aber durch wagnersche Quellenarbeit absichern. Reines Streben ohne Prüfung kann ebenso scheitern wie reines Sammeln ohne eigene Frage.",
    "compare": "Dies ist ein Beispiel für eine begründete Position, keine vorgeschriebene persönliche Antwort. Ersetze es durch eine eigene konkrete Schulerfahrung und prüfe einen Einwand.",
    "source": "https://projekt-gutenberg.org/authors/johann-wolfgang-von-goethe/books/faust-eine-tragoedie/chapter/5/"
  },
  "15": {
    "text": "Nach Wagners Abgang erlebt Faust den Abstand zwischen seinem hohen Selbstbild und seiner tatsächlichen Begrenztheit besonders schmerzhaft. Die Studierstube und die überlieferten Gegenstände erscheinen ihm als Gefängnis. Mit dem Giftbecher sucht er einen radikalen Übergang über die Bedingungen seines bisherigen Lebens hinaus. Der Todeswunsch ist in der Szene Ausdruck einer Krise, keine gelungene Lösung seines Erkenntnisproblems.",
    "compare": "Verbinde Erkenntnisgrenze, räumliche Enge und Griff zum Gift. Unterscheide Fausts Selbstauslegung von einer Bewertung seines Vorhabens.",
    "source": "https://projekt-gutenberg.org/authors/johann-wolfgang-von-goethe/books/faust-eine-tragoedie/chapter/5/"
  },
  "16": {
    "text": "Die Osterklänge und Gesänge lösen Erinnerungen an Kindheit, Gemeinschaft und frühere religiöse Erfahrung aus und halten Faust vom Trinken ab. Er gewinnt dadurch nicht plötzlich einen begründeten Auferstehungsglauben zurück. Die emotionale Bindung ans Leben ist stärker als seine intellektuelle Distanz. So zeigt sich, dass er nicht allein durch seinen Erkenntnisanspruch bestimmt ist.",
    "compare": "Belege die Kindheitserinnerung und seine fortbestehende Glaubensdistanz. Nicht eine neue wissenschaftliche Einsicht, sondern ein Erinnerungs- und Gefühlsgeschehen unterbricht die Krise.",
    "source": "https://projekt-gutenberg.org/authors/johann-wolfgang-von-goethe/books/faust-eine-tragoedie/chapter/5/"
  },
  "17": {
    "text": "Menschen verschiedener Stände verlassen an Ostern die Stadt, unterhalten sich, flirten, trinken und tanzen. Der Wechsel von Arbeit und Enge zu gemeinsamer Freizeit belebt auch Faust. Mit dem Vorspiel verglichen erscheint ein Publikum, das vielfältige unmittelbare Bedürfnisse hat und nicht nur auf hohe Kunst wartet. Die Szene gestaltet Volksleben literarisch; sie liefert allein keine repräsentative Sozialgeschichte des 18. oder 19. Jahrhunderts.",
    "compare": "Nenne mehrere beobachtbare Tätigkeiten und verbinde sie mit einem Publikumsbild des Vorspiels. Historische Aussagen müssen durch weitere Quellen abgesichert werden.",
    "source": "https://projekt-gutenberg.org/authors/johann-wolfgang-von-goethe/books/faust-eine-tragoedie/chapter/6/"
  },
  "18": {
    "text": "Wagner empfindet den öffentlichen Respekt als bewundernswerten Beweis für Fausts Ansehen. Faust erinnert sich dagegen an die gefährliche Heilpraxis seines Vaters und an die eigenen Beteiligungen. Für ihn verdeckt das Lob mögliche Schuld. Mir könnte Fausts selbstkritische Haltung näherliegen, sofern sie Verantwortung klärt und nicht bloss neue Selbstverachtung erzeugt.",
    "compare": "Unterscheide gesellschaftliche Anerkennung und tatsächlichen Nutzen der Behandlung. Die persönliche Präferenz darf anders ausfallen, wenn sie begründet wird.",
    "source": "https://projekt-gutenberg.org/authors/johann-wolfgang-von-goethe/books/faust-eine-tragoedie/chapter/6/"
  },
  "19": {
    "text": "Faust beschreibt zwei gegenläufige Bindungen: eine an sinnliche, irdische Nähe und eine an geistige Erhebung über das Gewöhnliche hinaus. Beide gehören zu ihm; ihr Widerstreit verhindert einfache Zufriedenheit. Ein heutiger Vergleich wäre der Konflikt zwischen Geborgenheit in vertrauten Beziehungen und dem Wunsch, für ein anspruchsvolles Vorhaben aufzubrechen.",
    "compare": "Die beiden Seelen sind eine Selbstbeschreibung, keine klinische Diagnose. Ein persönlicher Vergleich soll die Spannung erklären, nicht Faust und die eigene Person gleichsetzen.",
    "source": "https://projekt-gutenberg.org/authors/johann-wolfgang-von-goethe/books/faust-eine-tragoedie/chapter/6/"
  },
  "20": {
    "text": "Faust nimmt den Pudel von seinem Spaziergang mit in die Studierstube. Dessen Unruhe, Knurren und Bellen unterbrechen seine religiös-philosophische Sammlung und die Übersetzungsarbeit. Schliesslich vergrössert sich die Gestalt unnatürlich und verwandelt sich nach Fausts Beschwörungen in Mephisto. Der vermeintlich harmlose Gast wird als übernatürlicher Besucher kenntlich.",
    "compare": "Die Vorlage nennt Genesis; übersetzt wird hier tatsächlich der Anfang des Johannesevangeliums. Diesen sachlichen Unterschied sollte die Antwort ausdrücklich festhalten.",
    "source": "https://projekt-gutenberg.org/authors/johann-wolfgang-von-goethe/books/faust-eine-tragoedie/chapter/7/"
  },
  "21": {
    "text": "Faust erwägt nacheinander Wort, Sinn, Kraft und Tat als Wiedergabe des Anfangs des Johannesevangeliums. Er sucht einen Ausdruck für wirksames Schaffen und empfindet den blossen Wortbegriff als unzureichend. Bei Tat gelangt er vorläufig zu einem Entschluss. Seine Übersetzung ist zugleich eine eigenständige Weltdeutung, keine rein sprachlich gesicherte Korrektur des Originals.",
    "compare": "Korrigiere die Prämisse der Frage: Faust kommt zu einer vorläufigen Entscheidung. Zeige, was jede Ersetzung gegenüber der vorherigen betont.",
    "source": "https://projekt-gutenberg.org/authors/johann-wolfgang-von-goethe/books/faust-eine-tragoedie/chapter/7/"
  },
  "22": {
    "text": "Der Pudel wird unnatürlich gross und bedrohlich; Faust beschreibt wechselnde tierhafte und nebelartige Erscheinungen. Nach seinen Beschwörungen fällt der Nebel, und Mephisto tritt als fahrender Scholastikus hinter dem Ofen hervor. Die Verwandlung enthüllt, wer im Pudel verborgen war.",
    "compare": "Unterscheide die Verwandlungsschritte und die schliessliche menschliche Gestalt. Eine Filmbeobachtung sollte die konkrete Darstellung des Ausschnitts beschreiben.",
    "source": "https://projekt-gutenberg.org/authors/johann-wolfgang-von-goethe/books/faust-eine-tragoedie/chapter/7/"
  },
  "23": {
    "text": "Mephisto erscheint zunächst als gelehrter, beweglicher Gesprächspartner und begegnet Faust mit Ironie. Er beschreibt sich als verneinende, auf Zerstörung gerichtete Kraft. Seine Begründung lautet sinngemäss, Entstehendes verdiene den Untergang; zugleich bleibt er Teil einer umfassenderen Ordnung, in der seine Absicht nicht mit dem Ergebnis zusammenfällt. Seine Position kann als radikaler Negativismus kritisiert werden: Aus Vergänglichkeit folgt nicht automatisch Wertlosigkeit.",
    "compare": "Trenne Selbstbeschreibung, Begründung und eigene Kritik. Die Wirkung seiner Tätigkeit ist nicht einfach mit seinem erklärten Willen identisch.",
    "source": "https://projekt-gutenberg.org/authors/johann-wolfgang-von-goethe/books/faust-eine-tragoedie/chapter/7/"
  },
  "24": {
    "text": "Mephisto nimmt Fausts Überdruss an abstraktem Wissen auf und verspricht Erfahrungen, Welt und sinnlichen Genuss. Damit kann er den Gelehrten aus seiner Isolation führen. Den Anspruch auf umfassende Erkenntnis oder eine dauerhafte Erfüllung kann er jedoch nicht einfach einlösen. Der Gegensatz schafft die Grundlage für ihre spätere Wette.",
    "compare": "Vergleiche Fausts Ziel und das Angebot, statt Mephisto entweder als allmächtigen Helfer oder als völlig wirkungslos zu beschreiben.",
    "source": "https://projekt-gutenberg.org/authors/johann-wolfgang-von-goethe/books/faust-eine-tragoedie/chapter/7/"
  },
  "25": {
    "text": "Das unvollständig gezeichnete Pentagramm liess den Pudel eintreten, hindert Mephisto aber am regulären Ausgang. Er lässt Faust durch Geistergesang ablenken und einschläfern; eine Ratte beseitigt das Hindernis an der Schwelle. So entkommt er, ohne Fausts Forderung nach einer festen Vereinbarung zu erfüllen. Sein Abgang verschafft ihm Spielraum für den nächsten Besuch.",
    "compare": "Verbinde die räumliche Bindung mit Ablenkung und Manipulation. Mephisto ist in dieser Szene an Regeln gebunden.",
    "source": "https://projekt-gutenberg.org/authors/johann-wolfgang-von-goethe/books/faust-eine-tragoedie/chapter/7/"
  },
  "26": {
    "text": "Beim erneuten Besuch bietet Mephisto einen Weg aus Fausts Studierstubenexistenz an. Faust formuliert seine Verzweiflung und verwirft herkömmliche Bindungen und Versprechen des Lebens. Aus dem ersten abtastenden Gespräch wird eine Verhandlung über Dienst, Gegenleistung und die Bedingungen möglicher Befriedigung. Mephisto kann nun an offen ausgesprochene Bedürfnisse anknüpfen.",
    "compare": "Vergleiche den ersten Auftritt mit Fausts Fluch und der Vertragsverhandlung. Eine Veränderung der Gesprächslage ist noch keine vollständige Machtumkehr.",
    "source": "https://projekt-gutenberg.org/authors/johann-wolfgang-von-goethe/books/faust-eine-tragoedie/chapter/8/"
  },
  "27": {
    "text": "Faust will die ganze Spannweite menschlicher Erfahrung in sich aufnehmen: höchste und niedrigste Zustände, Freude und Schmerz. Er sucht keine gemütliche Unterhaltung und keine einfache dauerhafte Lust. Sein Anspruch bleibt masslos; gerade darin liegt eine mögliche Angriffsfläche für Mephistos Angebote.",
    "compare": "Belege den umfassenden Erfahrungsanspruch und unterscheide ihn von Mephistos Vorstellungen käuflichen oder sinnlichen Genusses.",
    "source": "https://projekt-gutenberg.org/authors/johann-wolfgang-von-goethe/books/faust-eine-tragoedie/chapter/8/"
  },
  "28": {
    "text": "Mephisto bietet Faust Dienste im Diesseits an und verlangt entsprechende Bindung im Jenseits. Faust verschärft die Sache zur Wette: Gelingt es Mephisto, ihn so zu befriedigen, dass er den Augenblick festhalten will, ist er unterlegen. Anders als im Prolog handelt Faust hier selbst und setzt auf die Unstillbarkeit seines Strebens. Gottes Vertrauen betrifft dagegen Fausts Entwicklung trotz Irrtum.",
    "compare": "Halte Dienstvertrag, Augenblickswette und Prologwette auseinander. Ein bloss angenehmer Augenblick ist nicht ohne Weiteres schon das festgelegte Verlieren.",
    "source": "https://projekt-gutenberg.org/authors/johann-wolfgang-von-goethe/books/faust-eine-tragoedie/chapter/8/"
  },
  "29": {
    "text": "Faust erwartet von Mephisto Zugang zu umfassender Welterfahrung, bezweifelt aber dessen Fähigkeit, seinen Anspruch wirklich zu erfüllen. Er behandelt ihn zugleich als Dienstleister und als unterlegenen Gesprächspartner, den er herausfordert. Diese Geringschätzung kann seine Abhängigkeit verdecken: Den Weg in die neue Lebenspraxis lässt er sich trotzdem von Mephisto organisieren.",
    "compare": "Verbinde mindestens eine Erwartung mit einem Beleg für den Umgangston. Selbstbewusstes Auftreten schliesst Manipulierbarkeit nicht aus.",
    "source": "https://projekt-gutenberg.org/authors/johann-wolfgang-von-goethe/books/faust-eine-tragoedie/chapter/8/"
  },
  "30": {
    "text": "Der Kleidertausch ermöglicht Mephisto, gegenüber dem wartenden Schüler als akademische Autorität aufzutreten. Faust lässt sich auf den Rollenwechsel ein, während Mephisto äussere Form und Gewohnheit als wirksame Mittel vorführt. Die Szene zeigt, wie leicht Amt, Kleidung und selbstsicherer Ton Glaubwürdigkeit erzeugen können. Fausts Bedenken gegen Täuschung sind dabei weniger konsequent als sein eigener Anspruch auf Wahrhaftigkeit.",
    "compare": "Unterscheide, wer in welcher Situation die Rolle spielt. Die spätere falsche Zeugenaussage über Marthes Mann ist eine andere Täuschungssituation.",
    "source": "https://projekt-gutenberg.org/authors/johann-wolfgang-von-goethe/books/faust-eine-tragoedie/chapter/8/"
  },
  "31": {
    "text": "Mephisto karikiert die Logik als geistige Dressur, die Medizin als Feld der Selbstinszenierung und des Zugriffs auf Patienten, die Juristerei als Fortsetzung ererbter Ungerechtigkeit und die Theologie als Arbeit mit autoritativen Worten. Darin liegen prüfbare Einwände gegen starre Ausbildung und missbrauchte Autorität. Für einen heutigen Faktencheck müsste man sie jedoch an konkreten Studienplänen, beruflichen Standards und Praxisbelegen untersuchen; die Satire beweist keine Aussage über alle heutigen Studiengänge.",
    "compare": "Dies ist der literarische Lösungskern, kein abgeschlossener aktueller Faktencheck. Ergänze für jedes untersuchte Fach eine datierte Hochschul- oder Fachquelle und einen passenden Gegenbeleg.",
    "source": "https://projekt-gutenberg.org/authors/johann-wolfgang-von-goethe/books/faust-eine-tragoedie/chapter/8/"
  },
  "32": {
    "text": "Mephisto stellt abstrakte Theorie und lebendige Erfahrung gegeneinander und verspottet gelehrte Zergliederung. Berechtigt ist die Frage, ob Wissen seinen Gegenstand verfehlt oder institutionelle Macht verdeckt. Problematisch wird daraus die pauschale Abwertung von Vernunft und methodischer Prüfung, weil sie gegen Täuschung gerade schützen können. Seine Wissenschaftskritik ist zudem Teil einer Verführungsstrategie und deshalb nicht interesselos.",
    "compare": "Ein aktueller Vergleich benötigt einen konkreten Fall. Unterscheide Kritik an einer Methode oder Institution von der Verwerfung wissenschaftlicher Prüfung überhaupt.",
    "source": "https://projekt-gutenberg.org/authors/johann-wolfgang-von-goethe/books/faust-eine-tragoedie/chapter/8/"
  },
  "33": {
    "text": "Faust möchte seine bisherige Enge verlassen und unmittelbar am Leben teilnehmen. Mephisto übersetzt diesen offenen Wunsch in einen von ihm geführten Weg durch gesellschaftliche Vergnügungen und sinnliche Erfahrungen. Indem er Auswahl, Tempo und Zugang kontrolliert, lenkt er den scheinbar selbstbestimmten Aufbruch. Dass Faust Bewegung will, macht nicht jedes Angebot zu einer Erfüllung seines Ziels.",
    "compare": "Vergleiche Fausts allgemeinen Wunsch mit Mephistos konkreten Mitteln. Belege die Lenkung an Vorschlägen und Gesprächsführung.",
    "source": "https://projekt-gutenberg.org/authors/johann-wolfgang-von-goethe/books/faust-eine-tragoedie/chapter/8/"
  },
  "34": {
    "text": "Die Kneipe ist von Trinken, Liedern, Spott und rasch umschlagender Gemeinschaft geprägt. Politische Äusserungen wirken als grosse Rede im kleinen Kreis; der Spott über Herrschaft steht neben nationalen und alltäglichen Ressentiments. Die Handlung gehört in eine frühneuzeitlich geprägte Faustwelt, während Goethes Bearbeitung spätere Erfahrungen mit verarbeitet. Eine exakte historische Datierung lässt sich aus dem Trinkgespräch allein nicht gewinnen.",
    "compare": "Nenne beobachtete Verhaltensweisen. Unterscheide die dargestellte Zeit, Goethes Entstehungszeit und den Blick einer Inszenierung von 1960.",
    "source": "https://projekt-gutenberg.org/authors/johann-wolfgang-von-goethe/books/faust-eine-tragoedie/chapter/9/"
  },
  "35": {
    "text": "Im Flohlied erhält ein unbedeutender Günstling durch die Willkür des Königs Rang und Privilegien. Die Umgebung muss seine Schädlichkeit ertragen und darf sich nicht wehren. Das verspottet höfische Günstlingswirtschaft. Mephisto kann solche Herrschaft durchschauen und dennoch selbst manipulativ handeln; Gesellschaftskritik macht ihn nicht automatisch zu einem demokratischen Befreier.",
    "compare": "Erkläre die Zuordnung von Floh, König und Hof. Politik überhaupt als teuflisch zu erklären wäre eine weitergehende Behauptung, die das Lied nicht allein begründet.",
    "source": "https://projekt-gutenberg.org/authors/johann-wolfgang-von-goethe/books/faust-eine-tragoedie/chapter/9/"
  },
  "36": {
    "text": "Mephisto äussert sich verächtlich über das umständliche Hexenritual und nennt als natürliche Alternative ein einfaches, körperlich tätiges Leben auf dem Land. Faust will diesen langsamen und beschwerlichen Weg nicht. Deshalb wird doch der Zaubertrank gewählt. Mephistos Skepsis richtet sich vor allem gegen Form und Aufwand des Hokuspokus, nicht gegen jeden übernatürlichen Eingriff.",
    "compare": "Vergleiche seinen Alternativvorschlag mit Fausts Ablehnung. Verwechsle den Teufel hier nicht mit einem konsequenten Aufklärer.",
    "source": "https://projekt-gutenberg.org/authors/johann-wolfgang-von-goethe/books/faust-eine-tragoedie/chapter/10/"
  },
  "37": {
    "text": "In der Hexenküche wird Faust durch einen Trank verjüngt und für erotische Anziehung empfänglicher gemacht. Mephisto schafft damit körperliche und psychische Voraussetzungen seines weiteren Programms. Das sogenannte Anti-Aging ist daher keine neutrale Gesundheitsmassnahme, sondern Teil der Lenkung von Fausts Wünschen.",
    "compare": "Beschreibe Ritual und Wirkung getrennt. Moderne Vergleiche sind als Vergleich zu markieren, nicht als medizinische Erklärung des Zaubers.",
    "source": "https://projekt-gutenberg.org/authors/johann-wolfgang-von-goethe/books/faust-eine-tragoedie/chapter/10/"
  },
  "38": {
    "text": "Faust sieht im Spiegel ein überwältigend schönes Frauenbild und reagiert mit starkem Begehren. Das Bild bindet seine Aufmerksamkeit an ein idealisiertes Objekt, das er zunächst nicht als konkrete Person mit eigener Perspektive wahrnimmt. Mephisto nutzt diesen Blick als Vorbereitung der erotischen Verführung. Die spätere Wirkung des Tranks verstärkt die Bereitschaft, Schönheit in anderen Frauen wiederzufinden.",
    "compare": "Unterscheide Spiegelbild und reale Frau. Eine Deutung als Projektion ist plausibel, wenn sie am Blick und an Fausts Reaktionen belegt wird.",
    "source": "https://projekt-gutenberg.org/authors/johann-wolfgang-von-goethe/books/faust-eine-tragoedie/chapter/10/"
  },
  "39": {
    "text": "Die Szene zeigt ein geheimnisvolles Gebräu und ein groteskes magisches Ritual; eine sachlich eindeutige Zutatenliste liefert sie nicht. Der Trank soll Faust verjüngen und seine erotische Wahrnehmung verändern. Faust reagiert auf das Hexeneinmaleins irritiert und hält die Worte für unsinnig, nimmt die angebotene Wirkung aber dennoch in Anspruch.",
    "compare": "Erfinde keine chemischen Bestandteile. Belege den Gegensatz zwischen Kritik am Ritual und Bereitschaft zur Nutzung.",
    "source": "https://projekt-gutenberg.org/authors/johann-wolfgang-von-goethe/books/faust-eine-tragoedie/chapter/10/"
  },
  "40": {
    "text": "Faust spricht Margarete als schönes Fräulein an und bietet seine Begleitung an. Sie weist beides zurück und erklärt, allein nach Hause gehen zu können. Seine Anrede greift eine Vertrautheit und gesellschaftliche Rolle vor, die sie nicht bestätigt. Die Ablehnung zeigt Selbstbehauptung; sie ist kein verkapptes Einverständnis.",
    "compare": "Belege ihre Antwort und unterscheide beobachtbare Zurückweisung von Vermutungen über spätere Gefühle.",
    "source": "https://projekt-gutenberg.org/authors/johann-wolfgang-von-goethe/books/faust-eine-tragoedie/chapter/11/"
  },
  "41": {
    "text": "Faust reagiert auf die Abweisung mit gesteigertem Begehren und verlangt von Mephisto, ihm das Mädchen zu verschaffen. Mephisto verweist zunächst auf ihre Unschuld und seine begrenzte Macht über sie, beginnt aber eine indirekte Annäherung zu organisieren. Fausts Ungeduld macht ihn von diesen Mitteln abhängig. Sein Anspruch, Margarete haben zu wollen, entspricht Mephistos Strategie, ihn über seine Wünsche zu lenken.",
    "compare": "Unterscheide Fausts Forderung und Mephistos Einschränkung. Margaretes Entscheidung wird in diesem Plan zunächst nicht als gleichberechtigt behandelt.",
    "source": "https://projekt-gutenberg.org/authors/johann-wolfgang-von-goethe/books/faust-eine-tragoedie/chapter/11/"
  },
  "42": {
    "text": "Margarete denkt über den unbekannten Mann nach und fragt sich, wer er sein könnte. Sein Auftreten erscheint ihr auffällig und möglicherweise vornehm; die Begegnung beschäftigt sie trotz ihrer entschiedenen Abweisung. Neugier lässt sich daraus ableiten, aber noch keine fertige Liebesentscheidung und keine nachträgliche Zustimmung zu seiner Anrede.",
    "compare": "Belege die Fragen, die sie sich stellt. Ihre späteren Gefühle dürfen nicht rückwirkend jede frühere Grenze aufheben.",
    "source": "https://projekt-gutenberg.org/authors/johann-wolfgang-von-goethe/books/faust-eine-tragoedie/chapter/12/"
  },
  "43": {
    "text": "Mephisto setzt auf ein verstecktes Schmuckgeschenk, das Neugier und Anziehung wecken soll. Faust erlebt im Zimmer dagegen einen Moment der Rührung und idealisiert Margaretes bescheidene, geordnete Lebenswelt. Zwischen diesem Reinheitsbild und dem heimlichen Eindringen samt Geschenk besteht eine Spannung. Seine Empfindung macht das Vorgehen nicht automatisch respektvoll.",
    "compare": "Vergleiche den praktischen Plan mit Fausts Rede im Zimmer. Eine gute Deutung berücksichtigt die Abwesenheit und fehlende Zustimmung Margaretes.",
    "source": "https://projekt-gutenberg.org/authors/johann-wolfgang-von-goethe/books/faust-eine-tragoedie/chapter/12/"
  },
  "44": {
    "text": "Margarete bemerkt das Schmuckkästchen, probiert den Schmuck und erlebt, wie stark äussere Zeichen von Reichtum das eigene Erscheinungsbild verändern. Das Thule-Lied erzählt von unverbrüchlicher Treue über den Tod der Geliebten hinaus; der König bewahrt den Becher als persönliches Erinnerungsstück. Das Treueideal kann zur späteren, durch Geschenke und Manipulation belasteten Liebesgeschichte in Spannung gesetzt werden.",
    "compare": "Erkläre sowohl Zimmerveränderung als auch Lied. Der Becher wird am Ende nicht vererbt; gerade seine besondere Bindung an die Geliebte ist entscheidend.",
    "source": "https://projekt-gutenberg.org/authors/johann-wolfgang-von-goethe/books/faust-eine-tragoedie/chapter/12/"
  },
  "45": {
    "text": "Margaretes Mutter hat den ersten Schmuck der Kirche übergeben. Mephisto ärgert sich darüber, dass seine Lockgabe der geplanten Wirkung entzogen wurde und andere Autoritäten davon profitieren. Faust bleibt auf Margarete fixiert und verlangt weiteren Schmuck. Der Streit betrifft damit sowohl das gescheiterte Mittel als auch die Ungeduld, mit der Faust seine Annäherung betreibt.",
    "compare": "Belege den Weg des Schmucks und die unterschiedlichen Reaktionen. Die Kirchenkritik ist Mephistos interessierte Sicht.",
    "source": "https://projekt-gutenberg.org/authors/johann-wolfgang-von-goethe/books/faust-eine-tragoedie/chapter/13/"
  },
  "46": {
    "text": "Marthe lebt mit einem abwesenden Mann und klagt über ihre ungesicherte, unbefriedigende Ehesituation. Sie wirkt praktisch, neugierig und für gesellschaftliche Anerkennung empfänglich. Margarete rät sie, den neuen Schmuck vor der Mutter zu verbergen und bei ihr anzulegen. So wird sie zur Vermittlerin eines heimlichen Handlungsspielraums, der Mephisto entgegenkommt.",
    "compare": "Verknüpfe ihre eigene Lage mit dem Rat. Eine blosse moralische Beschimpfung der Figur ersetzt keine Charakterisierung.",
    "source": "https://projekt-gutenberg.org/authors/johann-wolfgang-von-goethe/books/faust-eine-tragoedie/chapter/14/"
  },
  "47": {
    "text": "Mephisto gibt sich als Überbringer der Nachricht vom Tod von Marthes Mann aus und schmückt den Bericht mit erfundenen Einzelheiten. Marthe fragt neben Trauer und Empörung nach der rechtlichen Gewissheit ihres Status und möglichen Hinterlassenschaften. Mephisto verspricht einen zweiten Zeugen: Faust. Der nötige Nachweis schafft zugleich den Vorwand für eine neue Begegnung.",
    "compare": "Markiere den Bericht als Täuschung. Ein angekündigter Beweis ist in dieser Szene gerade noch kein verlässlicher Beleg.",
    "source": "https://projekt-gutenberg.org/authors/johann-wolfgang-von-goethe/books/faust-eine-tragoedie/chapter/14/"
  },
  "48": {
    "text": "Über Marthe kann Mephisto ein gemeinsames Treffen mit Margarete organisieren. Dafür soll Faust den Tod ihres Mannes bezeugen, obwohl er davon nichts weiss. Als Faust Bedenken anmeldet, relativiert Mephisto sie durch den Vergleich mit anderen ungesicherten Aussagen des Gelehrten. Ein wahrer Hinweis auf frühere Unsicherheit rechtfertigt jedoch kein bewusst falsches Zeugnis.",
    "compare": "Erkläre Zweck, verlangte Handlung und Überredung getrennt. Das Argument über Fausts frühere Reden hebt dessen aktuelle Verantwortung nicht auf.",
    "source": "https://projekt-gutenberg.org/authors/johann-wolfgang-von-goethe/books/faust-eine-tragoedie/chapter/15/"
  },
  "49": {
    "text": "Faust und Margarete sprechen in wachsender Nähe über ihre Person, ihren Alltag und ihre Gefühle; Margaretes soziale Unsicherheit begegnet Faust mit Bewunderung und Zuwendung. Marthe lenkt ihr Gespräch mit Mephisto dagegen auf Ehe und Bindung, während er ausweicht. Der Wechsel lässt aufkeimende Liebe und zweckgerichtetes Werben nebeneinander erscheinen. Die Paare bewegen sich im selben Garten, verfolgen aber nicht dieselben Ziele.",
    "compare": "Belege mindestens einen Wechsel zwischen den Paaren und deren unterschiedliche Gesprächsenden. Eine Filmfassung kann diese Parallelführung durch Wege und Schnitte betonen.",
    "source": "https://projekt-gutenberg.org/authors/johann-wolfgang-von-goethe/books/faust-eine-tragoedie/chapter/16/"
  },
  "50": {
    "text": "Mephisto drängt auf den Aufbruch und unterbricht damit die zunehmende Nähe. Eine bloss kurzfristige Affäre wäre für seine Strategie nicht unbedingt störend; die Frage setzt diesen Punkt zu pauschal voraus. Problematischer könnte eine Bindung sein, die Faust über leicht austauschbaren Genuss hinausführt. Margaretes unmittelbare, nicht nach Mephistos Kalkül organisierte Zuneigung begrenzt dann seine Steuerbarkeit, ohne dass er bereits machtlos wäre.",
    "compare": "Kennzeichne den taktischen Fehler als Deutung. Belege, ob die Unterbrechung eher praktische Gründe, Eifersucht auf Einfluss oder die Sorge vor einer stärkeren Bindung zeigt.",
    "source": "https://projekt-gutenberg.org/authors/johann-wolfgang-von-goethe/books/faust-eine-tragoedie/chapter/17/"
  },
  "51": {
    "text": "Faust erlebt die Natur als umfassenden Zusammenhang und erkennt zugleich seine gefährdende Wirkung auf Margarete. Er möchte die geliebte Person nicht bloss als Mittel des Genusses behandeln, bleibt aber von seinem Begehren getrieben. Mephisto verspottet die Erhebung und drängt auf Rückkehr und körperliche Erfüllung. Die Diskussion legt Fausts Verantwortung offen, statt ihm die Entscheidung abzunehmen.",
    "compare": "Vergleiche die Sprache der Naturerfahrung mit Mephistos Reduktion. Fausts Einsicht in Gefahr bedeutet noch nicht, dass er entsprechend handelt.",
    "source": "https://projekt-gutenberg.org/authors/johann-wolfgang-von-goethe/books/faust-eine-tragoedie/chapter/18/"
  },
  "52": {
    "text": "Margaretes kreisende Gedanken an Faust bestimmen Wahrnehmung und Arbeit. Wiederkehrende Formulierungen zeigen den Verlust innerer Ruhe; das Erinnern an seine körperliche Nähe steigert die Unruhe weiter. Das Spinnen ist reale Tätigkeit und zugleich ein Bild für die nicht endende Gedankenbewegung. In Schuberts Lied lässt sich die kreisende Klavierbewegung mit dem Rad und die Unterbrechung beim Kussgedanken mit dem stockenden Bewusstsein vergleichen.",
    "compare": "Den musikalischen Vergleich musst du an der gehörten Fassung prüfen. Beschreibe Wiederholung, Dynamik oder Unterbrechung statt Musik nur als traurig zu etikettieren.",
    "source": "https://projekt-gutenberg.org/authors/johann-wolfgang-von-goethe/books/faust-eine-tragoedie/chapter/19/"
  },
  "53": {
    "text": "Zwischen Faust und Gretchen besteht Zuneigung, aber keine spannungsfreie Verständigung. Gretchen versucht, den geliebten Mann auch in Fragen von Glauben und Verlässlichkeit zu verstehen. Faust antwortet zunächst ausweichend und lenkt auf Gefühl und Nähe. Das Gespräch zeigt, dass Intimität grundlegende Unterschiede nicht automatisch beseitigt.",
    "compare": "Belege Nähe und ein Zeichen verbleibender Unsicherheit. Die verniedlichende Formulierung der Frage darf die Ernsthaftigkeit des Gesprächs nicht verdecken.",
    "source": "https://projekt-gutenberg.org/authors/johann-wolfgang-von-goethe/books/faust-eine-tragoedie/chapter/20/"
  },
  "54": {
    "text": "Gretchen fragt Faust nach seinem Verhältnis zur Religion. Sie will wissen, ob seine Lebensführung mit ihrem eigenen Glauben und ihren Massstäben vereinbar ist. Die Gretchenfrage ist damit eine Gewissens- und Vertrauensfrage, die eine allgemeine Liebeserklärung nicht vollständig beantwortet.",
    "compare": "Unterscheide die konkrete Religionsfrage von der späteren übertragenen Bedeutung des Begriffs als entscheidende Grundsatzfrage.",
    "source": "https://projekt-gutenberg.org/authors/johann-wolfgang-von-goethe/books/faust-eine-tragoedie/chapter/20/"
  },
  "55": {
    "text": "Faust möchte Gretchens Nähe erhalten, teilt aber ihre kirchlich bestimmte Glaubenspraxis nicht ohne Weiteres. Eine klare Verneinung könnte sie verletzen oder entfremden; eine einfache Zustimmung wäre seinem eigenen Denken nicht angemessen. Daher verschiebt er die Frage auf umfassendes Gefühl und das Unvermögen von Namen. Das kann zugleich ein ernst gemeintes Bekenntnis und eine kommunikative Ausweichbewegung sein.",
    "compare": "Belege die Verschiebung der Frage. Widersprüchliche Funktionen einer Rede können gleichzeitig bestehen.",
    "source": "https://projekt-gutenberg.org/authors/johann-wolfgang-von-goethe/books/faust-eine-tragoedie/chapter/20/"
  },
  "56": {
    "text": "Faust beschreibt das Göttliche als umfassende, in Natur und menschlicher Erfahrung gegenwärtige Wirklichkeit und betont die Unzulänglichkeit eindeutiger Benennungen. Diese Rede kann pantheistisch gelesen werden, ohne daraus automatisch ein vollständiges philosophisches System zu machen. Für Aufrichtigkeit spricht die Nähe zu früheren Naturerfahrungen; für taktisches Ausweichen die konkrete Situation. Eine abgewogene Lösung hält beide Beobachtungen zusammen.",
    "compare": "Die Aufgabenformulierung unterstellt ein Vorschützen. Diese Unterstellung ist selbst zu prüfen; begründete Zustimmung oder Ablehnung ist möglich.",
    "source": "https://projekt-gutenberg.org/authors/johann-wolfgang-von-goethe/books/faust-eine-tragoedie/chapter/20/"
  },
  "57": {
    "text": "Gretchen empfindet Mephistos Gegenwart als kalt, lieblos und abstossend; sie meint, in seiner Nähe kaum beten zu können. Ihre Begründung stützt sich auf Eindruck, Verhalten und Wirkung auf sie, nicht auf eine ausdrücklich gesicherte Kenntnis seiner teuflischen Identität. Dramatisch erkennt sie eine Gefahr, die Faust trotz seines Wissens relativiert.",
    "compare": "Trenne Erfahrung, Deutung und gesicherte Figurenkenntnis. Ein Gefühl kann eine wichtige Warnung sein, ist aber kein allgemeingültiger Identitätsbeweis.",
    "source": "https://projekt-gutenberg.org/authors/johann-wolfgang-von-goethe/books/faust-eine-tragoedie/chapter/20/"
  },
  "58": {
    "text": "Faust und Gretchen verabreden eine nächtliche Begegnung. Damit die Mutter nichts bemerkt, soll Gretchen ihr ein Schlafmittel geben, dessen Harmlosigkeit Faust versichert. Der Plan verbindet das Vertrauen der Liebenden mit Heimlichkeit und einem erheblichen Risiko. Die spätere Katastrophe macht sichtbar, wie problematisch die ungeprüfte Versicherung war.",
    "compare": "Unterscheide das erklärte Ziel, die damalige Behauptung über das Mittel und die später berichtete Wirkung.",
    "source": "https://projekt-gutenberg.org/authors/johann-wolfgang-von-goethe/books/faust-eine-tragoedie/chapter/20/"
  },
  "59": {
    "text": "Mephisto kommentiert Gretchens Fragen spöttisch als Prüfung, ob Faust sich ihren religiösen Erwartungen fügt. Er reduziert ihr ernstes Anliegen auf ein Instrument weiblicher Einflussnahme. Diese Deutung passt zu seiner zynischen Sicht auf Bindungen, erklärt aber Gretchens Sorge um Glauben, Vertrauen und Mephistos Gegenwart nur unvollständig.",
    "compare": "Vergleiche seine Zusammenfassung mit dem tatsächlichen Gespräch. Eine Figurenrede über ein Gespräch ist selbst eine interessierte Interpretation.",
    "source": "https://projekt-gutenberg.org/authors/johann-wolfgang-von-goethe/books/faust-eine-tragoedie/chapter/20/"
  },
  "60": {
    "text": "Lieschen berichtet abwertend über die schwangere Bärbelchen und die Aussicht auf öffentliche Schande. Gretchen erinnert sich an ihr eigenes früheres Mitverurteilen und erkennt sich nun in der Lage der Ausgegrenzten wieder. Ihr Schweigen und Selbstgespräch zeigen Scham, Angst und veränderte moralische Wahrnehmung. Die Szene nimmt den drohenden gesellschaftlichen Ausschluss vorweg.",
    "compare": "Belege den Gegensatz zwischen Lieschens Urteil und Gretchens Selbstbezug. Die Szene ist nicht bloss beiläufiger Dorftratsch.",
    "source": "https://projekt-gutenberg.org/authors/johann-wolfgang-von-goethe/books/faust-eine-tragoedie/chapter/21/"
  },
  "61": {
    "text": "Gretchen wendet sich an die schmerzensreiche Mutter Maria und bittet aus ihrer Not heraus um Zuwendung. Das Bild der leidenden Mutter bietet eine Identifikations- und Ansprechmöglichkeit, während ihre eigene Lage kaum öffentlich sagbar ist. Schuldempfinden, Einsamkeit und Furcht vor Schande bilden das Dilemma. Das Gebet artikuliert Hilfebedürftigkeit, nicht schon eine Lösung der sozialen Situation.",
    "compare": "Verbinde Anrede, Körper- und Schmerzbilder mit ihrer Lage. Nicht alles muss als ausdrücklich ausgesprochene Tatsachenmitteilung gelesen werden.",
    "source": "https://projekt-gutenberg.org/authors/johann-wolfgang-von-goethe/books/faust-eine-tragoedie/chapter/22/"
  },
  "62": {
    "text": "Valentin ist Gretchens Bruder und Soldat. Er war stolz auf die öffentlich anerkannte Ehrbarkeit seiner Schwester und erlebt die Gerüchte nun als Angriff auf die eigene Ehre. Seine Heimkehr verbindet familiäre Bindung mit dem Wunsch nach Vergeltung. Dass er den Ruf der Schwester vor allem als seine eigene Angelegenheit behandelt, begrenzt seine Fürsorge.",
    "compare": "Belege den Wechsel von Stolz zu Beschämung. Ehrvorstellungen erklären sein Handeln, rechtfertigen es aber nicht automatisch.",
    "source": "https://projekt-gutenberg.org/authors/johann-wolfgang-von-goethe/books/faust-eine-tragoedie/chapter/23/"
  },
  "63": {
    "text": "Faust und Mephisto kommen nachts zu Gretchens Haus; Mephisto verbindet den Besuch mit der Aussicht auf einen Schatz und einer anzüglichen Serenade. Der Gesang macht das sexuelle Anliegen demonstrativ hörbar und provoziert. Valentin reagiert auf die beiden und zerstört Mephistos Instrument. So kippt die heimliche Annäherung in eine öffentliche Konfrontation.",
    "compare": "Unterscheide Fausts Besuchsabsicht, Mephistos zusätzliche Lockung und die Funktion des Liedes.",
    "source": "https://projekt-gutenberg.org/authors/johann-wolfgang-von-goethe/books/faust-eine-tragoedie/chapter/23/"
  },
  "64": {
    "text": "Valentin greift die nächtlichen Besucher an. Mephisto lenkt den Kampf, pariert beziehungsweise lähmt Valentins Gegenwehr und fordert Faust zum Zustechen auf. Faust versetzt den tödlichen Stich. Mephistos Hilfe erklärt den Ausgang, hebt Fausts Beteiligung und Verantwortung aber nicht auf.",
    "compare": "Ordne Handlung, Anleitung und Wirkung getrennt zu. Weder hat Faust völlig allein gekämpft noch ist der Stich deshalb nicht seine Handlung.",
    "source": "https://projekt-gutenberg.org/authors/johann-wolfgang-von-goethe/books/faust-eine-tragoedie/chapter/23/"
  },
  "65": {
    "text": "Faust und Mephisto fliehen, während andere Menschen dem verwundeten Valentin zu Hilfe kommen. Mephisto behandelt die Lage vor allem als Gefahr für die beiden; Faust entzieht sich zunächst der unmittelbaren Verantwortung vor Ort. Die Reaktionen zeigen die Differenz zwischen Selbstrettung, gesellschaftlicher Anteilnahme und der Lage des Sterbenden. Eine moralische Bewertung muss diese verschiedenen Positionen benennen.",
    "compare": "Belege die konkrete Reaktion jeder genannten Figur. Aussagen über das Publikum sind eigene Wirkungsdeutungen und brauchen Inszenierungsbeobachtungen.",
    "source": "https://projekt-gutenberg.org/authors/johann-wolfgang-von-goethe/books/faust-eine-tragoedie/chapter/23/"
  },
  "66": {
    "text": "Valentin verurteilt Gretchen öffentlich als sexuell entehrt und sagt ihr weitere Ausgrenzung voraus. Er verbindet den eigenen Tod mit der Wiederherstellung seines Ehrbildes, statt die Schwester zu schützen. Gretchen ist erschüttert und versucht, ihn als Bruder anzusprechen. Die Szene zeigt, wie familiäre und gesellschaftliche Verurteilung ihre Not verschärfen.",
    "compare": "Der Ausdruck für ihre angebliche Schande gehört zu Valentins Urteil, nicht zu einer neutralen Beschreibung ihrer Person.",
    "source": "https://projekt-gutenberg.org/authors/johann-wolfgang-von-goethe/books/faust-eine-tragoedie/chapter/23/"
  },
  "67": {
    "text": "Im Zwinger sucht Gretchen bei Maria eine mitfühlende Instanz. Im Dom wird sie dagegen durch Schuldvorwürfe des Bösen Geistes und die Gerichtsbilder des Chors bedrängt; sie erlebt Enge und bricht zusammen. Ihre Not erscheint nun stärker verinnerlicht und kaum noch durch einen Hilferuf abzufangen. Die Aufgabenbezeichnung Gottesstimme ist problematisch: Der Böse Geist und der liturgische Chor dürfen nicht mit einer eindeutigen direkten Rede Gottes gleichgesetzt werden.",
    "compare": "Vergleiche Sprecher, Bilder und körperliche Reaktionen. Eine Deutung als Gewissensstimme ist möglich, muss aber als Deutung ausgewiesen werden.",
    "source": "https://projekt-gutenberg.org/authors/johann-wolfgang-von-goethe/books/faust-eine-tragoedie/chapter/24/"
  },
  "68": {
    "text": "Faust und Mephisto steigen zum Brocken im Harz auf, wo die Walpurgisnacht stattfindet. Faust lässt sich von Landschaft, Licht und fremden Erscheinungen anziehen. Mephisto bewegt sich im Hexenmilieu vertrauter und zielgerichteter. Der Weg führt aus der bürgerlichen Welt in einen Raum der Entgrenzung, der zugleich neue Formen der Lenkung bereithält.",
    "compare": "Vergleiche ihre Reaktionen auf konkrete Erscheinungen. Der Aufstieg allein bedeutet noch keine innere Befreiung Fausts.",
    "source": "https://projekt-gutenberg.org/authors/johann-wolfgang-von-goethe/books/faust-eine-tragoedie/chapter/25/"
  },
  "69": {
    "text": "Das Irrlicht soll den Weg weisen, bewegt sich aber unzuverlässig und spricht in einer spielerisch schwankenden Weise. Damit passt die Form seines Auftretens zu einem Führer, auf dessen Richtung man sich nicht selbstverständlich verlassen kann. Mephisto versucht diese Unbeständigkeit seinem Zweck zu unterwerfen. Das Motiv verbindet Orientierung und Irreführung.",
    "compare": "Belege die Beziehung zwischen Sprache und Bewegung. Eine symbolische Deutung braucht mindestens eine konkrete Beobachtung.",
    "source": "https://projekt-gutenberg.org/authors/johann-wolfgang-von-goethe/books/faust-eine-tragoedie/chapter/25/"
  },
  "70": {
    "text": "Hexen, phantastische Gestalten, erotische Begegnungen und satirische Stimmen bilden ein heterogenes, rauschhaftes Geschehen. Die Entgrenzung lockert vertraute Ordnungen, legt aber zugleich Begierden, Machtansprüche und gesellschaftliche Eitelkeiten bloss. Für Mephisto ist der Betrieb ein Mittel zur Ablenkung Fausts. Das Ganze nur als sinnlosen Spuk zu behandeln würde die einzelnen sozialen und politischen Stimmen übergehen.",
    "compare": "Wähle zwei konkrete Erscheinungen aus und begründe ihre jeweilige Funktion. Nicht jede Gestalt muss derselben Allegorie zugeordnet werden.",
    "source": "https://projekt-gutenberg.org/authors/johann-wolfgang-von-goethe/books/faust-eine-tragoedie/chapter/25/"
  },
  "71": {
    "text": "Mephisto bietet immer neue Reize und versucht, Faust im unmittelbaren Genuss zu halten. Das könnte dessen weiterführendes Streben stillstellen, doch nicht jede Unterhaltung erfüllt schon die Wettbedingung. Fausts Wahrnehmung einer an Gretchen erinnernden Erscheinung unterbricht den Betrieb und bringt eine verdrängte Bindung zurück. Er ist dadurch nicht automatisch gerettet, entzieht sich aber für einen Moment der reinen Zerstreuung.",
    "compare": "Prüfe die Wettbedingung genau und belege die Unterbrechung. Die Formel Tod durch Entertainment ist eine moderne Deutung, keine wörtliche Diagnose des Dramas.",
    "source": "https://projekt-gutenberg.org/authors/johann-wolfgang-von-goethe/books/faust-eine-tragoedie/chapter/25/"
  },
  "72": {
    "text": "Der General klagt über fehlendes Vertrauen in die Völker, der Minister über den Anspruch der Menge auf eigenes Urteil. Der Parvenü verteidigt den eigenen Besitzstand gegen eine als unsicher beklagte Gegenwart. Der Autor ärgert sich über eine Jugend, die seine Autorität nicht mehr anerkennt. Gemeinsam beklagen sie Wandel; die jeweiligen Gründe entlarven jedoch eigene Macht- und Anerkennungsinteressen.",
    "compare": "Ordne jeder Figur ihr besonderes Interesse zu. Der gemeinsame kulturkritische Ton beweist nicht, dass ihre Klagen sachlich berechtigt sind.",
    "source": "https://projekt-gutenberg.org/authors/johann-wolfgang-von-goethe/books/faust-eine-tragoedie/chapter/25/"
  },
  "73": {
    "text": "Mephisto bezeichnet Lilith als Adams erste Frau und warnt Faust vor der fesselnden Macht ihrer Haare. Im Walpurgisnachtkontext verdichtet sie erotische Anziehung und die Gefahr des Gebundenseins. Ihre Herkunft gehört zu ausserbiblischen Überlieferungen; die Erzählung von einer ersten Frau Adams ist nicht einfach der Wortlaut der Genesis. Eine weitergehende Traditionsgeschichte müsste zusätzlich recherchiert werden.",
    "compare": "Trenne Mephistos Beschreibung, die Funktion in dieser Szene und externe Überlieferungen. Die Frauengestalt darf nicht unbesehen als allgemeines Urteil über Frauen gelten.",
    "source": "https://projekt-gutenberg.org/authors/johann-wolfgang-von-goethe/books/faust-eine-tragoedie/chapter/25/"
  },
  "74": {
    "text": "Oberon und Titania, Elfenwelt, Theater im Theater und Hochzeitsmotiv verweisen auf Shakespeares Sommernachtstraum. Goethe gestaltet daraus ein eigenes satirisches Spiel mit vielen kurzen Stimmen. Die Anspielung eröffnet einen Vergleich von Streit, Verwandlung und Versöhnung, macht beide Stücke aber nicht identisch. Für die Recherche wäre zuerst Shakespeares Stück selbst und danach eine belegte Erläuterung heranzuziehen.",
    "compare": "Belege mindestens eine Figuren- und eine Motivverbindung. Eine Quellenangabe und eine konkrete Vergleichsstelle gehören zum selbst auszuführenden Rechercheteil.",
    "source": "https://projekt-gutenberg.org/authors/johann-wolfgang-von-goethe/books/faust-eine-tragoedie/chapter/26/"
  },
  "75": {
    "text": "Das Spiel verbindet die Wiedervereinigung von Oberon und Titania mit spöttischen Ratschlägen zur Ehe, unter anderem mit Distanz und zeitweiliger Trennung. Daraus lässt sich eine ironische Gegenposition zur Vorstellung ableiten, gelingende Liebe müsse ständige Verschmelzung bedeuten. Der satirische Ton verhindert aber, daraus ohne Weiteres Goethes verbindliches Beziehungsrezept zu machen.",
    "compare": "Belege den konkreten Ratschlag und seinen Ton. Eine wörtliche Lebensanweisung wäre nur eine von mehreren, begründungspflichtigen Lesarten.",
    "source": "https://projekt-gutenberg.org/authors/johann-wolfgang-von-goethe/books/faust-eine-tragoedie/chapter/26/"
  },
  "76": {
    "text": "Der Walpurgisnachtstraum bietet ein wechselndes satirisches Bühnenspiel innerhalb des Dramas. Im Text fehlt eine ausführliche abschliessende Selbstauskunft Fausts über dessen Wirkung. Daher lässt sich Ablenkung als mögliche dramaturgische Funktion diskutieren, aber keine sichere innere Reaktion allein aus dem Spektakel folgern. Für die Filmfrage muss Fausts sichtbares Verhalten im Ausschnitt ausgewertet werden.",
    "compare": "Eine gute Lösung benennt hier eine Grenze der Beleglage. Unterscheide Figurenreaktion, vermutete Wirkung und tatsächliche eigene Zuschauererfahrung.",
    "source": "https://projekt-gutenberg.org/authors/johann-wolfgang-von-goethe/books/faust-eine-tragoedie/chapter/26/"
  },
  "77": {
    "text": "Faust hat erfahren, dass Gretchen im Kerker auf ihr Urteil wartet, und klagt Mephisto an, ihn darüber im Unwissen gelassen und zerstreut zu haben. Mephisto hält ihm seine eigene Beteiligung entgegen. Der Wechsel zur Prosa lässt die Auseinandersetzung schroff und unmittelbar erscheinen. Fausts Empörung ist verständlich, reicht aber nicht aus, um seine Verantwortung auf den Begleiter abzuwälzen.",
    "compare": "Der genaue Weg der Nachricht wird in dieser Szene nicht ausführlich erzählt. Erfinde deshalb keinen sicheren Informationsgeber, wenn die Filmfassung keinen zeigt.",
    "source": "https://projekt-gutenberg.org/authors/johann-wolfgang-von-goethe/books/faust-eine-tragoedie/chapter/27/"
  },
  "78": {
    "text": "Faust verlangt, Gretchen zu retten. Mephisto erklärt, die Haft nicht einfach durch seine Macht aufheben zu können, bietet aber Hilfe beim Zugang und bei der Flucht an; Faust muss selbst handeln. Er erinnert zugleich an die Gefahr, die Faust wegen Valentins Tod in der Stadt droht. Die Rettung verlangt also ein eigenes Risiko und kann nicht bloss an den Diener delegiert werden.",
    "compare": "Unterscheide Zugangshilfe und Gretchens tatsächliche Befreiung. Die Grenze von Mephistos Macht ist Bestandteil seiner Antwort.",
    "source": "https://projekt-gutenberg.org/authors/johann-wolfgang-von-goethe/books/faust-eine-tragoedie/chapter/27/"
  },
  "79": {
    "text": "Gretchen erscheint im Kerker schwer verstört und wechselt zwischen Angst, Erinnerung, Lied und verschiedenen zeitlichen Wirklichkeiten. Die Hinrichtung, das getötete Kind und ihre Beziehungen sind in ihrem Sprechen miteinander verschränkt. Einzelne klare Erkenntnisse stehen neben Verkennungen. Literarisch lässt sich dieser Zustand als extreme seelische Zerrüttung beschreiben; eine sichere klinische Diagnose liefert die Szene nicht.",
    "compare": "Belege unterschiedliche Sprechweisen und Wahrnehmungen. Verwirrung darf nicht mit dem vollständigen Verlust jeder Urteilskraft gleichgesetzt werden.",
    "source": "https://projekt-gutenberg.org/authors/johann-wolfgang-von-goethe/books/faust-eine-tragoedie/chapter/29/"
  },
  "80": {
    "text": "Gretchen hält den eintretenden Faust zunächst für den Henker beziehungsweise einen Vollstrecker ihres bevorstehenden Todes. Die erwartete Hinrichtung bestimmt, wie sie das Geschehen wahrnimmt. Fausts Gegenwart erreicht sie deshalb nicht sofort als Rückkehr des Geliebten. Das Missverständnis macht die Macht ihrer Angst und die Brüchigkeit ihrer Orientierung sichtbar.",
    "compare": "Belege die anfängliche Anrede und unterscheide sie vom späteren Wiedererkennen.",
    "source": "https://projekt-gutenberg.org/authors/johann-wolfgang-von-goethe/books/faust-eine-tragoedie/chapter/29/"
  },
  "81": {
    "text": "Gretchen bittet darum, ihr Kind noch stillen zu dürfen, obwohl sie dessen Tod zugleich in anderen Äusserungen kennt. Ihr Wunsch stellt eine fürsorgliche Mutterbeziehung her, die in der Handlung bereits zerstört ist. Für Faust und das Publikum entsteht die Spannung zwischen dem lebendigen Bedürfnis und dem Wissen um das Geschehene. Das kann Mitleid und Entsetzen auslösen; die genaue Wirkung bleibt an der Inszenierung zu prüfen.",
    "compare": "Unterscheide Wunsch, Tatsachenlage und Zuschauerwirkung. Der Wunsch ist nicht als verlässlicher Bericht über ein noch lebendes Kind zu lesen.",
    "source": "https://projekt-gutenberg.org/authors/johann-wolfgang-von-goethe/books/faust-eine-tragoedie/chapter/29/"
  },
  "82": {
    "text": "An Fausts vertrauter Stimme erkennt Gretchen den Geliebten wieder und sucht frühere Nähe. Faust drängt auf rasche Flucht, während sie Liebe, Schuld und die Toten ihrer Familie zur Sprache bringen muss. Sie berichtet von der Mutter und dem Kind und entwirft eine Grabordnung für sich und ihre Angehörigen. Die Begegnung scheitert auch daran, dass körperliche Befreiung ihr Bedürfnis nach Verantwortung und verlässlicher Zuwendung nicht erfüllt.",
    "compare": "Verfolge Erkennen, Kussbitte, Geständnisse, Familienbilder und Fluchtverweigerung in ihrer Reihenfolge. Ihre Ablehnung ist nicht nur aus Verwirrung zu erklären.",
    "source": "https://projekt-gutenberg.org/authors/johann-wolfgang-von-goethe/books/faust-eine-tragoedie/chapter/29/"
  },
  "83": {
    "text": "Gretchen stellt sich den Morgen und die öffentliche Hinrichtung in konkreten Schreckensbildern vor. Menge, Gericht und das unmittelbar bevorstehende Ende bestimmen ihre Wahrnehmung des letzten Tages. Sie erkennt eine Ausweglosigkeit, die Fausts Fluchtplan nicht einfach aufhebt. Die Bilder verbinden individuelle Todesangst mit dem gesellschaftlichen Vollzug des Urteils.",
    "compare": "Belege einzelne Bilder ihres Sprechens. Zukunftsvorstellung, Erinnerung und aktuelles Kerkerereignis können ineinander übergehen.",
    "source": "https://projekt-gutenberg.org/authors/johann-wolfgang-von-goethe/books/faust-eine-tragoedie/chapter/29/"
  },
  "84": {
    "text": "Gretchen weist die von Mephisto begleitete Flucht zurück und übergibt sich dem göttlichen Gericht. Mephisto erklärt sie für gerichtet; eine Stimme von oben widerspricht mit der Rettungszusage. Faust wird von Mephisto fortgezogen, während Gretchens Rufen nach ihm nachklingt. Die Unterscheidung von weltlicher Verurteilung und göttlicher Rettung verhindert, das Ende allein als Erfolg des Teufels zu lesen. Wie Freiheit, Schuldannahme und Gnade zusammenwirken, bleibt eine begründungspflichtige Deutungsfrage.",
    "compare": "Ordne die gegensätzlichen Urteile ihren Sprechern zu. Der Ausgang von Faust I ist nicht bereits das Ende von Fausts gesamter Geschichte.",
    "source": "https://projekt-gutenberg.org/authors/johann-wolfgang-von-goethe/books/faust-eine-tragoedie/chapter/29/"
  }
};
